int main() {
    long long n;
    cin >> n;
    long long prev = 0, len = 0, sum = 0, bl = 0, bs = 0;
    for (long long i = 0; i < n; i++) {
        long long x;
        cin >> x;
        if (i > 0 && x > prev) {
            len++;
            sum += x;
        } else {
            len = 1;
            sum = x;
        }
        if (len > bl) {
            bl = len;
            bs = sum;
        }
        prev = x;
    }
    cout << bl << " " << bs << endl;
    return 0;
}

